from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

_RATES = {
    "inland": Decimal("4.20"),
    "coastal": Decimal("5.75"),
    "highland": Decimal("9.10"),
}
_CENT = Decimal("0.01")


def kessler_freight_charge(weight_kg, zone, is_perishable) -> float:
    try:
        base_rate = _RATES[zone]
    except (KeyError, TypeError):
        raise ValueError("invalid zone")

    try:
        weight = Decimal(str(weight_kg))
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError("weight_kg must be greater than 0")

    if not weight.is_finite() or weight <= 0:
        raise ValueError("weight_kg must be greater than 0")

    subtotal = min(weight, Decimal("10")) * base_rate
    subtotal += min(max(weight - Decimal("10"), Decimal("0")), Decimal("40")) * Decimal("0.60") * base_rate
    subtotal += max(weight - Decimal("50"), Decimal("0")) * Decimal("0.35") * base_rate
    subtotal = subtotal.quantize(_CENT, rounding=ROUND_HALF_UP)

    if subtotal % Decimal("1.00") == Decimal("0.00"):
        subtotal -= Decimal("2.00")

    if is_perishable and zone != "highland":
        subtotal += Decimal("18.50")

    return float(subtotal.quantize(_CENT, rounding=ROUND_HALF_UP))
